<!--vbase-->
<template>
  <q-card style="width: 600px">
    <form @submit.prevent.stop="submitNewColumFrom">
      <q-toolbar class="text-white secondary-toolbar">
        <q-toolbar-title
          ><span class="text-weight-bold">{{
            $t('add_new_table_column')
          }}</span>
        </q-toolbar-title>

        <q-btn flat round dense icon="close" v-close-popup />
      </q-toolbar>

      <q-card-section class="q-pt-none">
        <div style="margin-bottom: 20px" class="row full-width mb-10 mt-8">
          <div class="full-width">
            <q-input
              :label="$t('title') + '*'"
              v-model="new_column_model['label']"
              :hint="$t('custom_column_hint')"
              outlined
              class="full-width"
            />
          </div>
        </div>

        <div class="row full-width">
          <div class="full-width">
            <q-checkbox
              class="q-mb-sm"
              :label="$t('is_it_required')"
              v-model="new_column_model['column_required']"
            />
          </div>
        </div>

        <div class="row full-width">
          <div class="full-width">
            <q-select
              outlined
              v-model="new_column_model['type']"
              class="col-sm-6 col-md-6 col-lg-6"
              :options="column_type"
              :label="$t('select_column_type') + '*'"
              emit-value
              map-options
              :error-message="$t('field_required')"
              :error="new_column_model['type_error']"
            >
              <template v-slot:append>
                <q-icon
                  name="close"
                  @click.stop="new_column_model['type'] = ''"
                  class="cursor-pointer"
                />
              </template>
              <template v-slot:option="scope">
                <q-item v-bind="scope.itemProps">
                  <q-item-section>
                    <q-item-label>{{ scope.opt.label }}</q-item-label>
                  </q-item-section>
                </q-item>
              </template>
            </q-select>
          </div>
        </div>

        <div class="row full-width" v-if="isViewColumnListView()">
          <div class="full-width">
            <q-select
              outlined
              tabindex="0"
              v-model="new_column_model['table_name']"
              error-message="Field is required"
              :error="new_column_model['table_name_error']"
              :options="tables_list"
              :loading="table_list_loading"
              emit-value
              map-options
              :label="$t('select_table')"
            />
          </div>
        </div>
      </q-card-section>

      <q-card-actions align="right">
        <q-btn class="highlighted-back" :label="$t('cancel')" v-close-popup />

        <q-btn
          type="submit"
          color="primary"
          class="q-mr-sm"
          :label="$t('proceed')"
        />
      </q-card-actions>
    </form>
  </q-card>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { i18n } from 'src/boot/i18n';
import axios from 'axios';
import { defineComponent, ref } from 'vue';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import helperMixin from 'src/mixins/helperMixin.js';
import { api, getAuthorizationToken } from 'pages/APIs';
import { getOrgId } from 'src/utils/organization/org_id_helper';
export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  props: {
    is_table_training_doc: {
      type: Boolean,
      default: false,
    },
    is_table_extraction_view: {
      type: Boolean,
      default: true,
    },
    table_name: {
      type: String,
      default: '',
    },
    parent_view: {
      type: String,
      default: 'table_extraction',
    },
    tables: {
      type: Array,
      default: () => [],
    },
    columns_list: {
      type: Object,
      default: () => ({}),
    },
    tables_list: {
      type: Array,
      default: () => [],
    },
    table_list_loading: {
      type: Boolean,
      default: false,
    },
  },
  components: {},
  data() {
    return {};
  },
  setup() {
    let model = {} as { [k: string]: any };
    return {
      new_column_model: ref(model),
      table_train: ref(false),
      token: ref(''),
      docId: '',
      column_type: [
        { label: i18n.t('select_column_type'), value: '' },
        { label: i18n.t('amount'), value: 'AMOUNT' },
        { label: 'STRING', value: 'STRING' },
        { label: i18n.t('invoice_date'), value: 'DATE' },
        { label: i18n.t('number'), value: 'NUMBER' },
        { label: 'BOOLEAN', value: 'BOOLEAN' },
        { label: i18n.t('currency'), value: 'CURRENCY' },
      ],
    };
  },
  watch: {},
  mounted() {
    this.isDocForTraining();
    this.setNewModel();
    this.SelectDefaultTable();
  },
  methods: {
    setNewModel() {
      this.new_column_model['column_required'] = false;
      this.new_column_model['table_name'] = this.$t('select_table');
      this.new_column_model['label'] = '';
      this.new_column_model['type'] = '';
      this.new_column_model['type_error'] = false;
    },
    async submitNewColumFrom() {
      try {
        if (
          !this.new_column_model['type'] ||
          this.new_column_model['type'] == ''
        ) {
          this.new_column_model['type_error'] = true;
          return;
        }

        this.vaildateColumnLabel();
        await this.saveNewColumn();

        // close the dialog
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
    SelectDefaultTable() {
      const tables = Array.isArray(this.tables_list) ? this.tables_list : [];
      const defaultTable = tables[1];

      if (tables.length <= 3 && defaultTable?.value) {
        this.new_column_model['table_name'] = defaultTable.value;
      }
    },
    vaildateColumnLabel() {
      this.new_column_model['column_name'] = '';
      let label = this.new_column_model['label'];
      label = label.replace(/\ /g, '_');
      if (!label || label == '') {
        throw {
          message: 'Title required',
        };
      }

      const re = /^[a-zA-Z0-9\_]+$/;
      if (!re.test(label)) {
        throw {
          message: 'Only use Words and Numbers for title',
        };
      }

      this.new_column_model['column_name'] = label
        .replace(/[^0-9a-zA-Z_ ]/g, '')
        .toUpperCase();
      if (
        this.columns_list.hasOwnProperty(this.new_column_model['column_name'])
      ) {
        throw {
          message: this.$t('title_already_exists'),
        };
      }

      if (
        !this.new_column_model['column_name'] ||
        this.new_column_model['column_name'] == ''
      ) {
        throw {
          message: 'Title required',
        };
      }

      if (
        this.isViewColumnListView() &&
        (!this.new_column_model['table_name'] ||
          this.new_column_model['table_name'].length == 0)
      ) {
        throw {
          message: 'Table required',
        };
      }
    },
    async saveNewColumn() {
      let response: any;
      try {
        let formData = new FormData();
        // creating from tbv3 OR create from List
        formData.append('column_name', this.new_column_model['column_name']);
        formData.append('column_type', this.new_column_model['type']);
        formData.append('title', this.new_column_model['label']);
        formData.append(
          'is_required',
          this.new_column_model['column_required'],
        );

        formData.append('doc_id', this.docId);
        formData.append('table_data', JSON.stringify(this.tables));
        let table_name = this.isViewColumnListView()
          ? this.new_column_model['table_name']
          : this.table_name;
        formData.append('table_name', table_name);

        if (this.is_table_training_doc === true) {
          formData.append('is_table_training_doc', true.toString());
        }
        formData.append('org_id', getOrgId());

        let token: string = await this.getToken();
        let api_url = api.create_document_table_column;
        if (this.is_table_extraction_view === false) {
          api_url = api.create_table_column;
        }
        response = await axios.post(api_url, formData, {
          headers: {
            Authorization: token,
          },
        });

        if (response.data.success === false) {
          if (response.data.message) {
            notify.error(response.data.message);
          } else {
            throw {
              message:
                'Response dont have table_data index/success is set to false',
            };
          }
        }

        this.dispatchSuccessEvent(response.data.table_data);
      } catch (err) {
        logError(err);
        throw { message: this.$t('title_already_exists_switcher') };
      }
      this.hideLoading();
    },
    dispatchSuccessEvent(table_data: any) {
      const event = new CustomEvent('custom_column_create', {
        detail: { tables: table_data },
      });
      document.dispatchEvent(event);
    },
    async getToken() {
      let token: string =
        this.token && this.token != null && this.token != ''
          ? this.token
          : await getAuthorizationToken();
      return token;
    },
    isDocForTraining() {
      if (
        this.$route.params.table_train &&
        this.$route.params.table_train === 'true'
      ) {
        this.table_train = true;
        this.token = String(this.$route.query.token);
        this.docId = String(this.$route.query.id);
      } else {
        this.docId = String(this.$route.params.id);
      }
    },
    isViewColumnListView() {
      return this.parent_view === 'columns_list' ? true : false;
    },
  },
});
</script>

<style lang="scss" scoped></style>
